command:
// ==========================================
// ⚙️ LUNAS WIRKUNG: APHASMAS SCHLEIER
//
// - ein selbst gewählter Schleier aus dem Inventar
// - keine Reichweitenprüfung
// - direkte Effektanlage auf dem eigenen Akteur über Block 5
// - keine GM-Anfrage
// - Wirkungskarte über Block 19.8
// - ein vorhandener Aphasmas-Schleier-Effekt wird ersetzt
// - fremde, nicht zu dieser Gabe gehörende Effekte bleiben erhalten
// ==========================================

(async function () {

    // +++ 1 - FRAMEWORK +++++++++++++++++++++++++++++++++++++++

    const frameworkUuid = "Compendium.dsk-havena-und-umland.makros.Macro.fHQ2OuDo3Fe3spBn";
    const frameworkFehlt =
        !globalThis.DSK?.Effekt?.Anwenden ||
        !globalThis.DSK?.EffektEnde?.Register ||
        !globalThis.DSK?.QS?.Ermitteln ||
        !globalThis.DSK?.GabenUI?.AnfrageKarteErstellen;

    if (frameworkFehlt) {
        const fwMacro = await fromUuid(frameworkUuid);

        if (!fwMacro) {
            return ui.notifications.error(
                "Luna sagt 🌙: Das DSK-Framework wurde nicht gefunden!"
            );
        }

        await fwMacro.execute();
        await new Promise(resolve => setTimeout(resolve, 150));
    }

    const DSK_FW = globalThis.DSK;

    if (
        !DSK_FW?.Effekt?.Anwenden ||
        !DSK_FW?.EffektEnde?.Register ||
        !DSK_FW?.QS?.Ermitteln ||
        !DSK_FW?.GabenUI?.AnfrageKarteErstellen
    ) {
        return ui.notifications.error(
            "Luna sagt 🌙: Das DSK-Framework wurde nicht vollständig geladen!"
        );
    }

    // +++ 2 - GRUNDDATEN ++++++++++++++++++++++++++++++++++++++

    const gabenName = "Aphasmas Schleier";
    const ahne = "Aphasma";
    const suchbegriff = "Schleier";
    const basisEffektName = `${gabenName} (${ahne})`;

    const basisBeschreibung =
        `Der Schleier gilt nun als geweiht. Solange er sichtbar getragen wird, ` +
        `erhält das Aphasmakind eine Erleichterung von <b>{BONUS} FW</b> ` +
        `auf <i>Umschmeicheln</i> und <i>Körperbeherrschung (Tanzen)</i>. ` +
        `Wirkt die Gabe auf einen zweiten Schleier, verliert der erste seine magische Wirkung.`;

    const dauerText = "Bis zum nächsten Vollmond";
    const abschlussText =
        "Der sanfte, silberne Schimmer der Mondgöttin verblasst langsam. " +
        "Der Stoff verliert sein übernatürliches Wesen. Aphasmas Segen ruht.";

    DSK_FW.EffektEnde.Register(
        "aphasmasschleier",
        basisEffektName,
        abschlussText
    );

    // +++ 3 - HILFSFUNKTIONEN +++++++++++++++++++++++++++++++++

    const raeumeQSAuf = async actor => {
        if (actor?.getFlag("world", "letzteGabenQS") !== undefined) {
            await actor.unsetFlag("world", "letzteGabenQS");
        }
    };

    const findeAlteSchleierEffekte = actor =>
        (actor?.effects || []).filter(effect => {
            const name = effect.name || effect.label || "";
            const istPassenderName =
                name === basisEffektName ||
                name.startsWith(`${basisEffektName} -`);

            const istUnserEffekt =
                effect.getFlag("dsk", "aphasmasschleier") === true ||
                effect.getFlag("dsk", "ahnenId") === "aphasmasschleier";

            return istPassenderName && istUnserEffekt;
        });

    const loescheEffekt = async effect => {
        if (!effect) return false;

        try {
            await effect.delete();
            return true;
        } catch (error) {
            console.error(
                "Aphasmas Schleier: Alter Effekt konnte nicht entfernt werden.",
                error
            );

            return false;
        }
    };

    const berechneBonus = qs =>
        Math.max(1, Math.round(Number(qs) / 2));

    // +++ 4 - WIRKENDER UND QS ++++++++++++++++++++++++++++++++

    let casterActor =
        canvas.tokens.controlled[0]?.actor ||
        game.user.character ||
        null;

    if (!casterActor) {
        casterActor =
            canvas.tokens.placeables
                .map(token => token.actor)
                .find(actor =>
                    actor?.getFlag(
                        "world",
                        "letzteGabenQS"
                    ) !== undefined
                ) ||

            game.actors.find(actor =>
                actor.getFlag(
                    "world",
                    "letzteGabenQS"
                ) !== undefined
            ) ||

            null;
    }

    if (!casterActor) {
        return ui.notifications.warn(
            "Luna sagt 🌙: Bitte wähle zuerst deinen Token aus, liebes Aphasmakind!"
        );
    }

    if (!game.user.isGM && !casterActor.isOwner) {
        return ui.notifications.warn(
            "Luna sagt 🌙: Du besitzt keine ausreichenden Rechte für diesen Akteur!"
        );
    }

    const casterName =
        DSK_FW.ResolveTokenName(casterActor);

    const qs = DSK_FW.QS.Ermitteln({
        actor: casterActor,
        gabenName,

        suchbegriffe: [
            "Aphasmas Schleier Probe",
            "Aphasmas Schleier"
        ],

        testDataObj:
            typeof testData !== "undefined"
                ? testData
                : null,

        fallback: 0,
        protokollieren: true
    });

    if (qs <= 0) {
        await raeumeQSAuf(casterActor);

        return ui.notifications.warn(
            "Luna sagt 🌙: Die Probe ist fehlgeschlagen oder die Qualitätsstufe konnte nicht ermittelt werden!"
        );
    }

    const bonus = berechneBonus(qs);
    const beschreibung =
        basisBeschreibung.replace(
            "{BONUS}",
            String(bonus)
        );

    // +++ 5 - SCHLEIER AUS DEM INVENTAR WÄHLEN ++++++++++++++++

    const gefundeneItems =
        casterActor.items.filter(item =>
            (item.name || "")
                .toLowerCase()
                .includes(suchbegriff.toLowerCase()) &&

            String(item.type || "")
                .toLowerCase() !== "ahnengabe"
        );

    if (!gefundeneItems.length) {
        await raeumeQSAuf(casterActor);

        return ui.notifications.warn(
            `Luna sagt 🌙: Kein passender Gegenstand (${suchbegriff}) im Inventar gefunden!`
        );
    }

    const optionen =
        gefundeneItems.map(item =>
            `<option value="${item.uuid}">${foundry.utils.escapeHTML(item.name)}</option>`
        ).join("");

    // +++ 6 - AUSWAHLDIALOG +++++++++++++++++++++++++++++++++++

    const dialogResult =
        await foundry.applications.api.DialogV2.wait({
            window: {
                title: gabenName
            },

            position: {
                width: 420
            },

            content: `
                <form>
                    <div style="font-family:'Signika',sans-serif;">
                        ${DSK_FW.UI.Header(
                            basisEffektName,
                            DSK_FW.Symbol(ahne)
                        )}

                        <div class="dskbox2" style="margin-top:10px;">
                            <p style="font-size:.95em;line-height:1.35;">
                                ${beschreibung}
                            </p>

                            <div style="margin-top:10px;">
                                <label style="font-weight:bold;font-size:.9em;">
                                    Wähle deinen Schleier:
                                </label>

                                <select name="gegenstandUuid"
                                    style="width:100%;padding:4px;margin-top:4px;font-family:'Signika',sans-serif;">
                                    ${optionen}
                                </select>
                            </div>

                            <hr style="margin:10px 0;">

                            <p style="text-align:center;font-weight:bold;">
                                Wirkungsdauer: ${dauerText}
                            </p>
                        </div>
                    </div>
                </form>
            `,

            rejectClose: false,

            buttons: [
                {
                    action: "anwenden",
                    label: "Gabe wirken",
                    icon: "fas fa-magic",
                    default: true,

                    callback: event => {
                        const form =
                            event.target.closest("form");

                        return form
                            ? new FormData(form).get("gegenstandUuid")
                            : null;
                    }
                },
                {
                    action: "abbrechen",
                    label: "Abbrechen",
                    icon: "fas fa-times",
                    callback: () => false
                }
            ]
        });

    if (!dialogResult || dialogResult === false) {
        await raeumeQSAuf(casterActor);
        return;
    }

    const item = await fromUuid(dialogResult);

    if (
        !item ||
        item.parent?.uuid !== casterActor.uuid
    ) {
        await raeumeQSAuf(casterActor);

        return ui.notifications.warn(
            "Luna sagt 🌙: Der ausgewählte Schleier konnte nicht mehr gefunden werden!"
        );
    }

    // +++ 7 - ALTEN EIGENEN EFFEKT ERSETZEN +++++++++++++++++++

    const alteEffekte =
        findeAlteSchleierEffekte(casterActor);

    for (const effect of alteEffekte) {
        const geloescht =
            await loescheEffekt(effect);

        if (!geloescht) {
            await raeumeQSAuf(casterActor);

            return ui.notifications.error(
                "Luna sagt 🌙: Der bisherige Schleier-Effekt konnte nicht entfernt werden!"
            );
        }
    }

    // +++ 8 - EFFEKT DIREKT ÜBER BLOCK 5 ++++++++++++++++++++++

    const finalerEffektName =
        `${basisEffektName} - ${item.name}`;

    const wirkungText =
        `Der Schleier <b>${item.name}</b> gilt nun als geweiht. ` +
        `Solange er sichtbar getragen wird, erhält das Aphasmakind eine Erleichterung von ` +
        `<b>${bonus} FW</b> auf <i>Umschmeicheln</i> und <i>Körperbeherrschung (Tanzen)</i>.` +
        `<br><br><b>Wirkungsdauer:</b> ${dauerText}` +
        `<br><b>Gabe gewirkt von:</b> ${casterName}`;

    const neuerEffekt =
        await DSK_FW.Effekt.Anwenden({
            name: finalerEffektName,
            ahne,
            beschreibung: wirkungText,
            gabeZiel: "",
            qs,
            ziel: casterActor,

            skills: [
                "Umschmeicheln",
                "Körperbeherrschung (Tanzen)"
            ],

            key: "system.skillModifiers.FW",
            formel: String(bonus),
            origin: casterActor.uuid,
            showIcon: 1,

            flags: {
                dsk: {
                    aphasmasschleier: true,
                    ahnenId: "aphasmasschleier",
                    casterUuid: casterActor.uuid,
                    casterName,
                    itemUuid: item.uuid,
                    itemName: item.name,
                    bonus,
                    qs
                }
            }
        });

    if (!neuerEffekt) {
        await raeumeQSAuf(casterActor);

        return ui.notifications.error(
            "Luna sagt 🌙: Aphasmas Segen konnte nicht auf den Schleier übertragen werden!"
        );
    }

    // +++ 9 - EFFEKT KONTROLLIEREN ++++++++++++++++++++++++++++

    const effektIstKorrekt =
        (neuerEffekt.name ||
            neuerEffekt.label ||
            "") === finalerEffektName &&

        neuerEffekt.getFlag(
            "dsk",
            "aphasmasschleier"
        ) === true &&

        neuerEffekt.getFlag(
            "dsk",
            "itemUuid"
        ) === item.uuid &&

        neuerEffekt.getFlag(
            "dsk",
            "casterUuid"
        ) === casterActor.uuid &&

        Number(
            neuerEffekt.getFlag(
                "dsk",
                "bonus"
            )
        ) === bonus &&

        Number(
            neuerEffekt.getFlag(
                "dsk",
                "qs"
            )
        ) === qs &&

        Array.isArray(neuerEffekt.changes) &&
        neuerEffekt.changes.length === 2 &&

        neuerEffekt.changes.every(change =>
            change.key === "system.skillModifiers.FW" &&
            change.mode === 0 &&
            String(change.value).includes(`+${bonus}`)
        );

    if (!effektIstKorrekt) {
        await loescheEffekt(neuerEffekt);
        await raeumeQSAuf(casterActor);

        return ui.notifications.error(
            "Luna sagt 🌙: Aphasmas Schleier wurde nicht vollständig angelegt!"
        );
    }

    // +++ 10 - WIRKUNGSKARTE ÜBER BLOCK 19.8 +++++++++++++++++

    await DSK_FW.GabenUI.AnfrageKarteErstellen({
        gabenName: basisEffektName,
        ahne,
        beschreibung,
        wirkender: casterName,

        ziele: [{
            name: item.name,
            rolle: "Geweihter Schleier"
        }],

        misserfolge: [],
        dauerText,

        gmBereich: false,
        angewendet: true,
        erfolgreich: true,
        anfragenderUserId: game.user.id
    });

    // +++ 11 - QS AUFRÄUMEN +++++++++++++++++++++++++++++++++++

    await raeumeQSAuf(casterActor);

    ui.notifications.info(
        `Luna sagt 🌙: ${item.name} wurde durch Aphasma geweiht.`
    );

}).call(this);
